def solve_standard(low, high):
    total = 0
    for s in range(low, high + 1):
        if s % 2 == 0:
            total += s**2
    return total

def solve_swapped(low, high):
    start = min(low, high)
    end = max(low, high)
    total = 0
    for s in range(start, end + 1):
        if s % 2 == 0:
            total += s**2
    return total

