import os, sys

def search_text(path, text):
    results = []
    for root, dirs, files in os.walk(path):
        for f in files:
            if f.endswith('.py'):
                try:
                    with open(os.path.join(root, f), 'r', encoding='utf-8', errors='ignore') as file:
                        if text in file.read():
                            results.append(os.path.join(root, f))
                except Exception:
                    pass
    return results

# Search python path
